import java.io.InputStream;
import java.io.OutputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    static class Edge implements Comparable<Edge> {
        int u, v, w;

        Edge(int u, int v, int w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }

        @Override
        public int compareTo(Edge o) {
            return Integer.compare(this.w, o.w);
        }
    }

    static int[] dsuParent;

    static int find(int i) {
        if (dsuParent[i] == i)
            return i;
        return dsuParent[i] = find(dsuParent[i]);
    }

    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner(System.in);
        FastOutput out = new FastOutput(System.out);

        int n = in.nextInt();
        int m = in.nextInt();
        int totalCells = n * m;

        long[] p = new long[totalCells];
        for (int i = 0; i < totalCells; i++) {
            p[i] = in.nextLong();
        }

        int maxEdges = 2 * totalCells;
        Edge[] edges = new Edge[maxEdges];
        int edgeCount = 0;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                int u = r * m + c;
                if (r + 1 < n) {
                    int v = (r + 1) * m + c;
                    int w = (int) Math.max(p[u], p[v]);
                    edges[edgeCount++] = new Edge(u, v, w);
                }
                if (c + 1 < m) {
                    int v = r * m + (c + 1);
                    int w = (int) Math.max(p[u], p[v]);
                    edges[edgeCount++] = new Edge(u, v, w);
                }
            }
        }

        Arrays.sort(edges, 0, edgeCount);

        int maxNodes = 2 * totalCells;
        int[] leftChild = new int[maxNodes];
        int[] rightChild = new int[maxNodes];
        int[] weight = new int[maxNodes];
        long[] sum = new long[maxNodes];
        dsuParent = new int[maxNodes];

        for (int i = 0; i < totalCells; i++) {
            sum[i] = p[i];
            leftChild[i] = -1;
            rightChild[i] = -1;
            dsuParent[i] = i;
        }

        int nextNode = totalCells;
        for (int i = 0; i < edgeCount; i++) {
            Edge e = edges[i];
            int rootU = find(e.u);
            int rootV = find(e.v);

            if (rootU != rootV) {
                int parent = nextNode++;
                dsuParent[parent] = parent;
                dsuParent[rootU] = parent;
                dsuParent[rootV] = parent;

                leftChild[parent] = rootU;
                rightChild[parent] = rootV;
                weight[parent] = e.w;
                sum[parent] = sum[rootU] + sum[rootV];
            }
        }

        int root = nextNode - 1;
        long[] ans = new long[maxNodes];
        ans[root] = sum[root];

        // DFS do topo para as folhas para determinar a resposta de cada nó
        int[] stack = new int[maxNodes];
        int top = 0;
        stack[top++] = root;

        while (top > 0) {
            int curr = stack[--top];
            int left = leftChild[curr];
            int right = rightChild[curr];

            if (left != -1) {
                int w = weight[curr];

                if (sum[left] >= w) {
                    ans[left] = ans[curr];
                } else {
                    ans[left] = sum[left];
                }
                stack[top++] = left;

                if (sum[right] >= w) {
                    ans[right] = ans[curr];
                } else {
                    ans[right] = sum[right];
                }
                stack[top++] = right;
            }
        }

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                int u = r * m + c;
                out.print(ans[u]);
                if (c + 1 < m) {
                    out.print(' ');
                }
            }
            out.print('\n');
        }

        out.flush();
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                ptr = 0;
                len = in.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            int res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') break;
                res = res * 10 + (c - '0');
                c = read();
            }
            return res;
        }

        long nextLong() throws IOException {
            int c = read();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = read();
            }
            long res = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') break;
                res = res * 10 + (c - '0');
                c = read();
            }
            return res;
        }
    }

    static class FastOutput {
        private final OutputStream out;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;

        FastOutput(OutputStream out) {
            this.out = out;
        }

        void print(char c) throws IOException {
            if (ptr >= buffer.length) flushBuffer();
            buffer[ptr++] = (byte) c;
        }

        void print(long x) throws IOException {
            if (x == 0) {
                print('0');
                return;
            }
            if (x < 0) {
                print('-');
                x = -x;
            }
            char[] digits = new char[20];
            int dCount = 0;
            while (x > 0) {
                digits[dCount++] = (char) ('0' + (x % 10));
                x /= 10;
            }
            while (dCount > 0) {
                print(digits[--dCount]);
            }
        }

        private void flushBuffer() throws IOException {
            if (ptr > 0) {
                out.write(buffer, 0, ptr);
                ptr = 0;
            }
        }

        void flush() throws IOException {
            flushBuffer();
            out.flush();
        }
    }
}
